G=load()

def components(g,bg):
    H,W=len(g),len(g[0]); seen=set(); best=None
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                comp={(r,c)}; q=deque([(r,c)])
                while q:
                    a,b=q.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]!=bg and (na,nb) not in comp:
                            comp.add((na,nb)); q.append((na,nb))
                scores=len(comp)*len({g[a][b] for a,b in comp})
                if best is None or scores>best[0]: best=(scores,comp)
    return best[1]

def f(g):
    H,W=len(g),len(g[0]); bg=g[0][0]
    comp=components(g,bg)
    rngs=list(comp); rmin=min(a for a,b in rngs); rmax=max(a for a,b in rngs)
    cmin=min(b for a,b in rngs); cmax=max(b for a,b in rngs)
    P=[[g[a][b] for b in range(cmin,cmax+1)] for a in range(rmin,rmax+1)]
    h,w=len(P),len(P[0])
    ar,ac=(h-1)//2,(w-1)//2
    out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in comp:
                for i in range(h):
                    for j in range(w):
                        rr,cc=r+i-ar,c+j-ac
                        if 0<=rr<H and 0<=cc<W:
                            out[rr][cc]=P[i][j]
    return out
