    seeds=[(r,c,gi[r][c]) for r in range(len(gi)) for c in range(len(gi[0])) if gi[r][c]!=bg and (r,c) not in set(big)]
    cnt={}
    for r,c,sc in seeds:
        # which offsets explain all cells covered by stamp centered on (r,c) matching go? just tally: does go contain the full tiled pattern at offsets matching sc positions?
        hit=False
        for ra in range(h):
