def vote_align(gi,go):
    H,W=len(gi),len(gi[0]); bg=gi[0][0]
    bbs=comps(gi,bg); big=max(bbs,key=len)
    rng=list(big); rmin=min(a for a,b in rng); rmax=max(a for a,b in rng)
    cmin=min(b for a,b in rng); cmax=max(b for a,b in rng)
    h,w=rmax-rmin+1,cmax-cmin+1
    P=[[gi[a][b] for b in range(cmin,cmax+1)] for a in range(rmin,rmax+1)]
    bl=set(big)
    best=[]
    for r in range(H):
        for c in range(W):
            if gi[r][c]==bg or (r,c) in bl: continue
            sc=gi[r][c]; votes={}
            for ra in range(h):
                for ca in range(w):
                    if P[ra][ca]!=sc: continue
                    mis=sum(1 for i in range(h) for j in range(w)
                            if 0<=r-ra+i<H and 0<=c-ca+j<W and go[r-ra+i][c-ca+j]!=P[i][j])
                    votes[(ra,ca)]=mis
            # best local offset per seed
            best_mis,mof=min(votes.items(),key=lambda x:x[1])
            best.append((r,c,sc,mof))
    return best
