from collections import deque
def comps_of(g,bg,conn=8):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y]!=bg and not seen[x][y]:
                                seen[x][y]=True; q.append((x,y))
                res.append(comp)
    return res

